def generate():
    documents = []
    policies = []
    for number,title,triggers,terms,action,question,related in ROWS:
        doc_id = f'guide_{number}'
        documents.append({'id':doc_id,'category':title,'content':f"관련단어: {', '.join(terms)}. 해결방안 및 준비물: {action} 병원에 확인할 내용: {question}"})
        policies.append({'document_id':doc_id,'scope':'visit_preparation_only','medical_review_status':'not_applicable_nonclinical',
                         'triggers':triggers,'terms':terms,'easy_text':action,'staff_question':question,
                         'related_original_ids':related,'language_level':1})
    OUT.mkdir(exist_ok=True)
    (OUT/'visit-preparation-extra.txt').write_text('# 서비스 작성 방문 준비 문서 27종 · 의료적 판단 없음\nmedical_knowledge_docs = '+json.dumps(documents,ensure_ascii=False,indent=2)+'\n')
    (OUT/'preparation-policies.json').write_text(json.dumps({'version':'1.0','policies':policies},ensure_ascii=False,indent=2)+'\n')
    vocabulary = [{'canonical':c,'aliases':a,'easy_expression':e,'professional_level':l,'easy_level':1}for c,a,e,l in VOCABULARY]
    (OUT/'vocabulary-levels.json').write_text(json.dumps({'version':'1.0','level_definition':{'1':'일상 표현','2':'진료·행정 용어','3':'전문 용어'},'assessment':'service_authored_heuristic_not_validated_readability_grade','terms':vocabulary},ensure_ascii=False,indent=2)+'\n')
    print(f'Generated {len(documents)} documents and {len(vocabulary)} vocabulary mappings')


if __name__ == '__main__':generate()
